```json
{
  "title": "Đà Lạt thong thả, cà phê ngắm phố",
  "summary": "Một ngày chậm rãi ở Đà Lạt, bớt đi bộ, thêm thời gian ngồi cà phê ngắm cảnh và ăn uống đúng kiểu người địa phương.",
  "stops": [
    {
      "poi_id": "p129",
      "kind": "activity",
      "must_do_id": "p129",
      "note": "Thung Lũng Tình Yêu vẫn là điểm nhấn, sáng sớm ở đây đẹp như tranh, tha hồ chụp ảnh mà không phải vội."
    },
    {
      "poi_id": "p191",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa trưa đúng chất Đà Lạt, bánh căn nóng hổi ăn kèm nước chấm, ngon quá (so tasty) là phải."
    },
    {
      "poi_id": "p165",
      "kind": "activity",
      "must_do_id": "p165",
      "note": "Chợ Đà Lạt buổi chiều nhộn nhịp, đi lòng vòng ngắm hàng hóa, ngửi mùi cà phê rang là thấy cuộc sống địa phương rồi."
    },
    {
      "poi_id": "p49",
      "kind": "activity",
      "must_do_id": null,
      "note": "Thay chỗ đi bộ xa bằng quán cà phê view đẹp, ngồi một chỗ nhìn phố núi lên đèn, đúng kiểu thong thả."
    },
    {
      "poi_id": "p33",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa tối ngồi xuống đàng hoàng, đồ ăn ngon, không gian ấm cúng, hợp với người thích ngồi lại lâu một chút."
    }
  ]
}
```

